mapper.select:
SELECT
COUNT(*)
FROM BOARD B
INNER JOIN BOARD_TYPE_SUB BTS ON B.B_SUB_NO = BTS.B_SUB_NO
INNER JOIN BOARD_TYPE_MAIN BTM ON BTS.B_MAIN_NO = BTM.B_MAIN_NO
WHERE 1=1



		AND B.B_STATUS = 'T'
		AND B.USER_ID = #{sessionId}


		AND B.B_STATUS = 'Y'




	AND BTM.B_MAIN_NO = #{bMainNo}



	AND B.B_SUB_NO = #{bSubNo}



	AND BTS.B_SUB_TYPE = #{integratedCategory}



	AND BTS.B_SUB_TYPE = #{localCategory}



	AND B.LOCAL_NO = #{localNo}



	AND (


				B.TITLE LIKE CONCAT('%', #{keyword}, '%')


				B.B_CONTENT LIKE CONCAT('%', #{keyword}, '%')


				B.USER_ID LIKE CONCAT('%', #{keyword}, '%')


				(
					B.TITLE LIKE CONCAT('%', #{keyword}, '%')
					OR B.B_CONTENT LIKE CONCAT('%', #{keyword}, '%')
					OR B.USER_ID LIKE CONCAT('%', #{keyword}, '%')
				)


	)

SELECT IFNULL(A.LIKE_CNT, 0) AS likeCnt, CASE WHEN B.BOARD_NO IS NULL THEN 'N' ELSE 'Y' END AS myLike FROM ( SELECT BOARD_NO, COUNT(*) AS LIKE_CNT FROM BOARD_LIKE WHERE BOARD_NO = #{boardNo} GROUP BY BOARD_NO ) A LEFT JOIN ( SELECT BOARD_NO FROM BOARD_LIKE WHERE BOARD_NO = #{boardNo}
AND USER_ID = #{sessionId}
) B ON A.BOARD_NO = B.BOARD_NO
UNION
SELECT 0 AS likeCnt, 'N' AS myLike FROM DUAL WHERE NOT EXISTS ( SELECT 1 FROM BOARD_LIKE WHERE BOARD_NO = #{boardNo} ) LIMIT 1

SELECT
BOARD_NO AS boardNo,
USER_ID AS userId
FROM BOARD_LIKE
WHERE BOARD_NO = #{boardNo}
AND USER_ID = #{userId}

mapper.delete:
DELETE FROM BOARD_LIKE
WHERE BOARD_NO = #{boardNo}
AND USER_ID = #{userId}

mapper.update:
UPDATE BOARD
SET VIEW_COUNT = VIEW_COUNT + 1
WHERE BOARD_NO = #{boardNo}

UPDATE BOARD SET B_SUB_NO = #{bSubNo}, LOCAL_NO =
#{localNo}
NULL
, TITLE = #{title}, B_CONTENT = #{bContent}, B_STATUS = #{bStatus}, PRIVATE = #{privateYn}, UPDATE_TIME = NOW() WHERE BOARD_NO = #{boardNo}

UPDATE BOARD_ALARM
SET READ_YN = 'Y'
WHERE ALARM_NO = #{alarmNo}
AND RECEIVER_ID = #{sessionId}
